// Tests for the unmanaged helpers in freeform.go (not generated by Speakeasy).
// The two Test*ThroughUnmarshalJSON cases exercise the call sites that
// 08-sdk-json-numbers.patch adds to json.go, so they fail on an unpatched
// regen: that is the signal the patch stopped applying.

package utils

import (
	"encoding/json"
	"reflect"
	"testing"
)

func TestUnmarshalFreeFormMapKeepsBigNumbersExact(t *testing.T) {
	raw := json.RawMessage(`{"big_int": 12345678901234567890, "wei": 1000000000000000000000, "dec": 0.123456789012345678, "nested": {"n": 9007199254740993}, "list": [18446744073709551616]}`)
	var m map[string]any
	if err := unmarshalFreeFormMap(raw, reflect.ValueOf(&m).Elem()); err != nil {
		t.Fatalf("unmarshalFreeFormMap: %v", err)
	}
	out, err := json.Marshal(m)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	for _, lexeme := range []string{"12345678901234567890", "1000000000000000000000", "0.123456789012345678", "9007199254740993", "18446744073709551616"} {
		if !containsLexeme(out, lexeme) {
			t.Errorf("lexeme %s lost: %s", lexeme, out)
		}
	}
}

func TestIsJSONNumberLiteral(t *testing.T) {
	cases := map[string]bool{
		`100`: true, ` 0.5 `: true, `-1e3`: true, `1000000000000000000000`: true,
		`"100"`: false, `null`: false, `true`: false, `{"a":1}`: false, `[1]`: false, ``: false, `abc`: false,
	}
	for in, want := range cases {
		if got := isJSONNumberLiteral(json.RawMessage(in)); got != want {
			t.Errorf("isJSONNumberLiteral(%q) = %v, want %v", in, got, want)
		}
	}
}

type numberIntoStringFixture struct {
	Amount  string           `json:"amount"`
	Maybe   *string          `json:"maybe,omitempty"`
	Kind    fixtureKind      `json:"kind"`
	Action  map[string]any   `json:"action"`
	Nested  []map[string]any `json:"nested"`
	Untouch string           `json:"untouch"`
}

type fixtureKind string

func (f numberIntoStringFixture) MarshalJSON() ([]byte, error) {
	return MarshalJSON(f, "", false)
}

func (f *numberIntoStringFixture) UnmarshalJSON(data []byte) error {
	return UnmarshalJSON(data, &f, "", false, nil)
}

// Exercises the patched call sites: numbers aimed at string-kinded fields keep
// their lexeme, free-form maps keep big integers, quoted strings are untouched.
func TestNumbersIntoStringFieldsThroughUnmarshalJSON(t *testing.T) {
	raw := `{"amount": 0.123456789012345678, "maybe": 1000000000000000000000, "kind": 42, "action": {"nonce": 12345678901234567890}, "nested": [{"n": 1e21}], "untouch": "0.10"}`
	var f numberIntoStringFixture
	if err := json.Unmarshal([]byte(raw), &f); err != nil {
		t.Fatalf("UnmarshalJSON: %v", err)
	}
	if f.Amount != "0.123456789012345678" {
		t.Errorf("amount = %q", f.Amount)
	}
	if f.Maybe == nil || *f.Maybe != "1000000000000000000000" {
		t.Errorf("maybe = %v", f.Maybe)
	}
	if f.Kind != "42" {
		t.Errorf("kind = %q", f.Kind)
	}
	if f.Untouch != "0.10" {
		t.Errorf("untouch = %q", f.Untouch)
	}
	out, err := json.Marshal(f)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	for _, lexeme := range []string{`"amount":"0.123456789012345678"`, `"nonce":12345678901234567890`, `"n":1e21`} {
		if !containsLexeme(out, lexeme) {
			t.Errorf("round trip lost %s: %s", lexeme, out)
		}
	}
}

func containsLexeme(haystack []byte, lexeme string) bool {
	return len(lexeme) > 0 && len(haystack) >= len(lexeme) && (string(haystack) == lexeme || indexOf(string(haystack), lexeme) >= 0)
}

func indexOf(s, sub string) int {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return i
		}
	}
	return -1
}
